INCLUDE_BLOCKS=(('Includes/Const/Include.inc','module ActionClass19SpawnConst','''
                ; Физические поля и исходные числовые параметры создания класса 19
                module ActionClass19SpawnConst
CountMask       equ #03                                                         ; младшие два бита, число оставшихся попыток 0..3
KeepUpper       equ #FC                                                         ; сохранение остальных шести битов ReuseByte родителя
KindMask        equ #1F                                                         ; исходные пять младших битов R
KindLimit       equ #1B                                                         ; 27, исходные коды от этого порога уменьшаются на пять
KindSubtract    equ #05                                                         ; свёртка кодов 27..31 и порог временной метки для кодов 0..4
TemporaryBit    equ #07                                                         ; временный бит 7 L/B, не разряд ReuseByte
ControlMask     equ #70                                                         ; биты 4..6 R, управляющий код после сдвига 1..8
ComponentDelta  equ #00C8                                                       ; положительное смещение 200 каждой компоненты ребёнка
ModelOffset     equ #98                                                         ; исходное байтовое смещение таблицы моделей
InitialState    equ #04                                                         ; StepFastRecordPhases, фазы вычисления копируются в 0D..0F
RateSubtract    equ #1E                                                         ; 30, вычитаемая часть родительского Unknown10
RateLimit       equ #46                                                         ; исключающий верхний порог 70
RateMaximum     equ #45                                                         ; максимальное записываемое значение 69
ChildClass      equ #13                                                         ; полный класс 19 десятично
ControlByte13   equ #14                                                         ; исходное значение байта 13 ребёнка, 20
ChildEffectMask equ #10                                                         ; бит 4 ReuseByte для нормализованных кодов 0..4
                endmodule
'''),)


def name_operands(region,function_address,operation):
    if (region,function_address)!=('Action',0x6417):return operation
    for register,fields in (('IX',{24:'ReuseByte',7:'OffsetPhase0',8:'OffsetPhase1',9:'OffsetPhase2',16:'Unknown10'}),
        ('IY',{6:'ModelOffset',10:'StateCode',11:'LinkedIndex',12:'LinkFlags',13:'Unknown0D',14:'Unknown0E',15:'TargetIndex',16:'Unknown10',17:'Unknown11',18:'ClassCode',19:'Unknown13',24:'ReuseByte',35:'Unknown23'})):
        for offset,name in fields.items():operation=operation.replace('('+register+'+#'+format(offset,'02X')+')','('+register+' + @FActionRecord.'+name+')')
    for offset in range(6):
        name='Components.Component'+str(offset//2)+('.High' if offset&1 else '.Low')
        for register in ('IX','IY'):operation=operation.replace('('+register+'+#'+format(offset,'02X')+')','('+register+' + @FActionRecord.'+name+')')
    for old,name in (('AND #03','CountMask'),('AND #FC','KeepUpper'),('AND #1F','KindMask'),('CP #1B','KindLimit'),('SUB #05','KindSubtract'),
        ('CP #05','KindSubtract'),('AND #70','ControlMask'),('LD DE, #00C8','ComponentDelta'),('SUB #1E','RateSubtract'),('CP #46','RateLimit'),('LD A, #45','RateMaximum'),('LD A, #10','ChildEffectMask')):
        operation=operation.replace(old,old.rsplit('#',1)[0]+'@ActionClass19SpawnConst.'+name)
    for operation_prefix in ('SET 7,','BIT 7,','RES 7,'):
        operation=operation.replace(operation_prefix,operation_prefix.replace('7,','@ActionClass19SpawnConst.TemporaryBit,'))
    for field,literal,name in (('ModelOffset','98','ModelOffset'),('StateCode','04','InitialState'),('ClassCode','13','ChildClass'),('Unknown13','14','ControlByte13')):
        operation=operation.replace('LD (IY + @FActionRecord.'+field+'), #'+literal,'LD (IY + @FActionRecord.'+field+'), @ActionClass19SpawnConst.'+name)
    for address,name in ((0xE9A1,'FindReusableRecord'),(0xE6C7,'RecordAddressToIndex'),(0xE6A7,'RecordIndexToAddress')):
        operation=operation.replace('CALL #'+format(address,'04X'),'CALL @Action.'+name+'.Entry')
    return (operation.replace('LD HL, #A01B','LD HL, @ActionCandidateListState.BeforeFirst')
            .replace('CP #FE','CP @ActionCandidateListConst.ListEnd').replace('CP #80','CP @ActionReuseConst.ReusableHigh'))
